<?php
declare(strict_types=1);require_once __DIR__.'/../config/bootstrap.php';
$admin=require_login();if(!in_array((string)$admin['role'],['admin','main_admin'],true)){http_response_code(403);exit('Admin only');}
$pdo=db();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();try{
  $id=(int)($_POST['request_id']??0);$action=(string)($_POST['action']??'');$note=trim((string)($_POST['note']??''));
  if(!in_array($action,['approve','reject'],true)||mb_strlen($note)>1000)throw new RuntimeException('Invalid review.');
  $pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM academic_change_requests WHERE id=? AND status='pending' FOR UPDATE");$s->execute([$id]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('This request is no longer pending.');
  if($action==='approve'){
   $valid=$pdo->prepare('SELECT 1 FROM academic_degree_intakes WHERE degree_id=? AND batch_id=? AND is_active=1');$valid->execute([$r['requested_degree_id'],$r['requested_batch_id']]);if(!$valid->fetchColumn())throw new RuntimeException('Requested degree/intake is no longer available.');
   $pdo->prepare('INSERT INTO student_academic_profiles(user_id,degree_id,batch_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE degree_id=VALUES(degree_id),batch_id=VALUES(batch_id)')->execute([$r['student_user_id'],$r['requested_degree_id'],$r['requested_batch_id']]);
   $pdo->prepare('INSERT INTO student_account_audit(student_user_id,admin_user_id,action) VALUES (?,?,?)')->execute([$r['student_user_id'],$admin['id'],'correct_enrollment']);
  }
  $pdo->prepare('UPDATE academic_change_requests SET status=?,admin_user_id=?,admin_note=?,reviewed_at=NOW() WHERE id=?')->execute([$action==='approve'?'approved':'rejected',$admin['id'],$note,$id]);
  $pdo->prepare('INSERT INTO notifications(user_id,actor_user_id,type,title,message,target_url,is_read) VALUES (?,?,?,?,?,?,0)')->execute([$r['student_user_id'],$admin['id'],'system','Academic change request '.($action==='approve'?'approved':'rejected'),$note!==''?$note:($action==='approve'?'Your programme/intake was updated.':'Your request was not approved.'),'dashboard/profile.php']);
  $pdo->commit();$notice='Request '.($action==='approve'?'approved':'rejected').'.';
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof RuntimeException?$ex->getMessage():'Unable to review request.';error_log($ex->getMessage());}
}
$status=(string)($_GET['status']??'pending');if(!in_array($status,['pending','approved','rejected','all'],true))$status='pending';
$sql='SELECT r.*,u.full_name,u.email,u.student_number,d.name degree_name,b.batch_code FROM academic_change_requests r JOIN users u ON u.id=r.student_user_id JOIN academic_degrees d ON d.id=r.requested_degree_id JOIN academic_batches b ON b.id=r.requested_batch_id'.($status==='all'?'':' WHERE r.status=?').' ORDER BY r.id DESC LIMIT 150';$stmt=$pdo->prepare($sql);$stmt->execute($status==='all'?[]:[$status]);$requests=$stmt->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Academic change requests | ULearn</title><style>:root{font-family:Inter,system-ui,Arial;background:#f6f7fb;color:#23253a}body{margin:0}.wrap{max-width:1000px;margin:auto;padding:30px 18px}.card{background:white;border:1px solid #e5e5ef;border-radius:18px;padding:22px;margin:16px 0;box-shadow:0 6px 24px #14162a09}a{color:#6f55d2;text-decoration:none}.muted{color:#73798a}textarea{width:100%;box-sizing:border-box;border:1px solid #d9dce8;border-radius:10px;padding:12px;font:inherit}button{border:0;background:#7057d8;color:white;border-radius:9px;padding:11px 15px;cursor:pointer;font:inherit}.reject{background:#f2edf8;color:#6b48a3}.actions{display:flex;gap:10px;margin-top:10px}.msg{padding:12px;border-radius:10px;background:#ede9fc}@media(prefers-color-scheme:dark){:root{background:#111421;color:#eee}.card{background:#1c1f2f;border-color:#34374b}textarea{background:#141727;color:white;border-color:#44465b}}</style>
<script src="<?= htmlspecialchars(url('assets/js/theme-global.js?v=20261107-2'), ENT_QUOTES, 'UTF-8') ?>"></script>
<link rel="stylesheet" href="<?= e(url('assets/css/admin-unified-v1.css?v=1')) ?>">
</head><body><main class="wrap"><a href="<?= e(url('admin/users.php')) ?>">← People & Accounts</a><h1>Academic change requests</h1><p class="muted">Review identity corrections before modifying locked student records.</p><?php if($error): ?><p class="msg"><?= e($error) ?></p><?php endif ?><?php if($notice): ?><p class="msg"><?= e($notice) ?></p><?php endif ?><nav><?php foreach(['pending','approved','rejected','all'] as $v): ?><a style="margin-right:16px;font-weight:<?= $v===$status?'700':'400' ?>" href="?status=<?= e($v) ?>"><?= ucfirst($v) ?></a><?php endforeach ?></nav><?php foreach($requests as $r): ?><section class="card"><strong><?= e($r['full_name']) ?></strong><p class="muted"><?= e($r['email']) ?> · ID <?= e($r['student_number']?:$r['student_user_id']) ?> · <?= e($r['created_at']) ?></p><p>Requested: <strong><?= e($r['degree_name']) ?> / <?= e($r['batch_code']) ?></strong></p><p>Reason: <?= e($r['reason']) ?></p><p>Status: <?= e($r['status']) ?></p><?php if($r['status']==='pending'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><label for="note-<?= (int)$r['id'] ?>">Admin note (optional)</label><textarea id="note-<?= (int)$r['id'] ?>" name="note" maxlength="1000" rows="2"></textarea><div class="actions"><button name="action" value="approve" onclick="return confirm('Approve and change this student academic profile?')">Approve & update</button><button class="reject" name="action" value="reject" onclick="return confirm('Reject this request?')">Reject</button></div></form><?php else: ?><p class="muted">Admin note: <?= e($r['admin_note']?:'—') ?></p><?php endif ?></section><?php endforeach ?><?php if(!$requests): ?><div class="card">No requests in this category.</div><?php endif ?></main></body></html>